-- Generated Interior CRM development starter. Never creates Auth users.
begin;
do $$declare org uuid='dddddddd-dddd-4ddd-8ddd-dddddddddddd';actor uuid='11111111-1111-4111-8111-111111111111';industry uuid;lead uuid=private.seed_uuid('business-os:demo:rahul');begin
if not exists(select 1 from public.organization_memberships where organization_id=org and user_id=actor and status='active') then raise notice 'CRM seed skipped: demo Owner absent';return;end if;
perform set_config('request.jwt.claim.sub',actor::text,true);
select id into industry from public.industries where key='interior_design';
update public.leads set next_follow_up_at=(select min(due_at) from public.lead_followups where lead_id=lead and status='pending') where id=lead;
end$$;commit;
